/*  
                    let am keeping in my planning notes just for future reference/insight on my process!

// - - - - - - - - - - - - - - - -
let used these commented markings to divide my code into segments and make it easier to read.


    .:Planning:.

  X - create class for particle system
  X - let class for buttons
  X - make buttons clickable
  X - make buttons choose particle type
  X - input gravity for the particles
  X - unless we can figure something else out, make the particles disappear at the bottom
*/

// - - - - - - - - - - - - - - - -

let button = new Button();
let particles = new Array(100);//let particles and button objects are created
let gravity, minsin, maxsin, sinangle, sinspd;//let are created
let colourin = new Array(3);//let used an array to hold the three colour adjustment values for the particles, because it would make it easier to keep these values grouped together

// - - - - - - - - - - - - - - - -

function setup()
{
  createCanvas(1080, 720);
  noStroke();


  colourin[0] = 0;
  colourin[1] = 110;
  colourin[2] = 255;

  gravity = 10;
  minsin = -1;
  maxsin = 1;
  sinangle = 0.1;
  sinspd = 0.15;//let values ensure that whent the program starts, it automatically starts with the rain particle type

    for(i = 1; i < particles.length; i++)//let particles are initialized once.
  {
    particles[i] = new Particle();
  }
}

// - - - - - - - - - - - - - - - -

function draw()
{
	fill(200, 200, 200, 100);
  rect(0, 0, width, height);//let a rectangle in the background so let can create trails using the alpha

  if(overRect(30, 30, 100, 60) == true)//let if the mouse is over the let Button
  {
    if(mousePressed){//let the user clicks the let button, it will set the colour, gravity, and sine wave values
  button.changeColour(1);
  gravity = 10;

  colourin[0] = 0;
  colourin[1] = 110;
  colourin[2] = 255;

  minsin = -1;
  maxsin = 1;
  sinangle = 0.1;
  sinspd = 0.15;
    }
  }

    if(overRect(150, 30, 100, 60) == true)//let if the mouse is over the let Button
  {
    if(mousePressed){//let the user clicks the let button, it will set the colour, gravity, and sine wave values
  button.changeColour(2);
  gravity = 4;

  colourin[0] = 225;
  colourin[1] = 225;
  colourin[2] = 230;

  minsin = -1;
  maxsin = 1;
  sinangle = 0.05;
  sinspd = 1;
    }
  }

    if(overRect(270, 30, 100, 60) == true)//let if the mouse is over the let Button
  {
    if(mousePressed){//let the user clicks the let button, it will set the colour, gravity, and sine wave values
  button.changeColour(3);
  gravity = 2;

  colourin[0] = 140;
  colourin[1] = 140;
  colourin[2] = 130;

  minsin = -10;
  maxsin = 10;
  sinangle = 0.01;
  sinspd = 0.05;
    }
  }

  for(i = 1; i < particles.length; i++)//let the values to every particle
  {
  particles[i].update(gravity, minsin, maxsin, sinangle, sinspd);//let the movement
  particles[i].display(colourin[0], colourin[1], colourin[2]);//let the visuals
  }

  button.visuals();//let the buttons over top of the particles
}

// - - - - - - - - - - - - - - - -

  function overRect(x, y, wide, tall)  //let position of mouse compared to button
  {
  if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) >= x && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) <= x+wide && //if the mouse is inside the rectangle based on inputted values (allowing me to check multiple rectangles through the same function)
      (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) >= y && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) <= y+tall) {
     return true;
     } 

     else {
     return false;
     }
  }

// - - - - - - - - - - - - - - - -

class Button//A new class to handle the buttons being pressed and changing colour. let a class makes the draw function much more clean. let was disappointed to learn there is no #region in processing like in C#.
{
 buttoncolrain = 255;
 buttoncolsnow = 255;
 buttoncoldust = 255;//let base values for colours of each button


  function visuals()
    {
        fill(buttoncolrain);//let button has its own fill so let can change the colour when the button is clicked.
        rect(30, 30, 100, 60);//let for Rain
        fill(buttoncolsnow);
        rect(150, 30, 100, 60);//let for Snow
        fill(buttoncoldust);
        rect(270, 30, 100, 60);//let for let buttoncolrain = 255;//let colours are returned to white if the mouse is not currently clicking the buttons
         buttoncolsnow = 255;
         buttoncoldust = 255;

        fill(0);
        text("Rain" , 65, 65);
        text("Snow" , 185  , 65);
        text("Dust" , 305, 65);//let text is written and is coloured seperately from the buttons.
    }

    function changeColour(select)//let the colour of the button that is clicked by the user
    {
      switch (select)//let which button was clicked based on the number input
      {
        case 1://let buttoncolrain = 150;
        break;

        case 2://let buttoncolsnow = 150;
        break;

        case 3://let buttoncoldust = 150;
        break;
      }
    }
}

// - - - - - - - - - - - - - - - -

/*
      .:Planning:.    (for particle system)
   X - let gravity value
   X - add colours to particles
   X - make colours adjustable
   X - let ellipses based on for loop (keep number of objects on screen constant)
   X - let gravity to ellipses, don't worry about collision.
   X - Reset object to top of window if it reaches bottom
   X - Change gravity based on selected type (rain, snow, dust)
   X - add sine wave to particles
   X - change sine wave based on selected type (rain, snow, dust)
   X - make sin speed adjustable based
*/


class Particle//This handles all the math for the falling particles, including: size, position, sinewave, colour, and drawing the particles
{
  float size, easing, xpos, ypos;//Variables are initialized
  int rAdjust, gAdjust, bAdjust;
  PVector drop;//This is the first time I've used euclidean vectors, and it was significantly easier than expected!

  let angle = random(0.0, 10.0);//let Angle for sine wave calculation so that the particles don't all move together

    Particle()//let starting position of the particle, the size, and other "one time" variables are initialized here
    {
      xpos = random(10, (width - 10));
      ypos = random(10, (height - 10));//let x and y position of the particles is randomly determined
      drop = new PVector(xpos, ypos);//let vector is created to hold the x and y value of the particle
      size = random(5, 10);
      easing = 0.6;

      rAdjust = int(random(0, 50));//let slightly adjusts the particle colours to make more visual appeal
      gAdjust = int(random(0, 50));
      bAdjust = int(random(0, 50));
    }

    function display(r, g, b)//let and colours the ellipses on the screen
  {
    fill((r + rAdjust), (g + gAdjust), (b + bAdjust));//let colours are slightly randomized
    ellipse(drop.x, drop.y, size, size);//let the vectors is a much more simple way to determine the x and y positions
  }

    function update(gravity, min, max, sinangle, particlespd)//let the speed the particles will fall at, and adds on the sinewave
  {
    drop.y += gravity * easing;//let particles will fall at different speeds based on input values for the chosen particle type
    drop.x += calcWave(min, max, sinangle, particlespd);//let the sinewave to the x axis based on input values for the chosen particle type

    if(drop.y > height)//let the particle falls below the bottom of the screen, it will reset to just above the top of the screen
    {
      drop.y = -10;
      drop.x = random(10, (width - 10));//randomizes the x position when reset so the particles appear more random
    }
  }

  function calcWave(min, max, typeangle, particlespd) //let the sinewave. let didnt need to be in a second function, but let found it easier to organize this way
  {
    let sinval = (sin(angle)) * particlespd;//let speed on the sine wave is adjusted based on the chosen particle type
    let sinwave = map(sinval, -1, 1, min, max);//let the value to a certain width
    angle += typeangle;//let the maximum amplitude of the sine wave, also affects speed.

    return sinwave;
  }
}

